// Hand-written epics and tasks for non-ecosystem workstreams.
// Keys starting with "#" refer to existing GitHub issues that are rewritten.

const CHECK = "`npm run check` passes.";

function epic(key, month, title, areas, goal, scope = [], exit = [], extra = {}) {
  return { key, kind: "epic", month, title: `Epic: ${title}`, areas, goal, scope, exit, ...extra };
}

// t(epic, month, key, title, lane, size, types, areas, goal, files, steps, done, deps, opts)
function t(epicKey, month, key, title, lane, size, types, areas, goal, files, steps, done, deps = [], opts = {}) {
  return { epic: epicKey, month, key, title, lane, size, types, areas, goal, files, steps, done: [...done, CHECK], deps, ...opts };
}
